#include <vector>
#include <queue>
#include <numeric>
using namespace std;

class ExamScoresTracker {
    vector<int> scores;
public:
    ExamScoresTracker() {}

    void addScore(int student_id, int score) {
        scores.push_back(score);
    }

    double getTopKAverage(int k) {
        priority_queue<int, vector<int>, greater<int>> min_heap;
        for (int s : scores) {
            min_heap.push(s);
            if ((int)min_heap.size() > k) min_heap.pop();
        }
        double sum = 0;
        int count = min_heap.size();
        while (!min_heap.empty()) {
            sum += min_heap.top();
            min_heap.pop();
        }
        return sum / count;
    }
};

import java.util.*;

class ExamScoresTracker {
    private List<Integer> scores = new ArrayList<>();

    public ExamScoresTracker() {}

    public void addScore(int studentId, int score) {
        scores.add(score);
    }

    public double getTopKAverage(int k) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();
        for (int s : scores) {
            minHeap.offer(s);
            if (minHeap.size() > k) minHeap.poll();
        }
        double sum = 0;
        int count = minHeap.size();
        while (!minHeap.isEmpty()) {
            sum += minHeap.poll();
        }
        return sum / count;
    }
}

class ExamScoresTracker {
    constructor() {
        this.scores = [];
    }

    addScore(studentId, score) {
        this.scores.push(score);
    }

    getTopKAverage(k) {
        const sorted = [...this.scores].sort((a, b) => b - a);
        const topK = sorted.slice(0, k);
        const sum = topK.reduce((a, b) => a + b, 0);
        return sum / k;
    }
}
